const express = require('express');
function createApp(store, processor) {
    const app = express();
    app.use(express.json());
    app.get('/api/health', (req, res) => {
        return res.json({ ok: true });
    });
    app.get('/api/entries', (req, res) => {
        return res.json({ entries: store.list() });
    });
    app.post('/api/entries', (req, res) => {
        try {
            const entry = store.create(req.body);
            return res.json({ item: entry });
        }
        catch (error) {
            return res.status(400).json({ error: 'Invalid entry' });
        }
    });
    app.delete('/api/entries/:id', (req, res) => {
        const id = req.params.id;
        try {
            const item = store.delete(id);
            return res.json({ deleted: item });
        }
        catch (error) {
            return res.status(500).json({ error: 'Internal Server Error' });
        }
    });
    app.get('/api/projects', (req, res) => {
        return res.json({ projects: store.list() });
    });
    app.get('/api/summary', (req, res) => {
        return res.json(processor({ entries: store.list() }));
    });
    return app;
}
module.exports = createApp;

