const React = require('react');
function App() {
  const [data, setData] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState(false);
  const [loadingDetails, setLoadingDetails] = React.useState(false);
  const [loadingEntries, setLoadingEntries] = React.useState(false);
  const [loadingSummary, setLoadingSummary] = React.useState(false);
  const [project, setProject] = React.useState('api-server');
  const [minutes, setMinutes] = React.useState(0);
  const [date, setDate] = React.useState(new Date());
  const [note, setNote] = React.useState('');

  const [summary, setSummary] = React.useState({
    total_minutes: 0,
    by_project: {},
    by_day: {},
    active_projects: [],
    busiest_day: {},
  });

  const handleProjectChange = (project) => {
    setProject(project);
  };

  const handleMinutesChange = (minutes) => {
    setMinutes(minutes);
  };

  const handleDateChange = (date) => {
    setDate(date);
  };

  const handleNoteChange = (note) => {
    setNote(note);
  };

  const handleFormSubmit = (e) => {
    e.preventDefault();
    setLoadingDetails(true);
    fetch(`/api/summary/${project}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ minutes: minutes, date: date, note: note }),
    })
      .then((response) => response.json())
      .then((data) => {
        setLoadingDetails(false);
        setSummary(data);
        setLoadingSummary(true);
      })
      .catch((error) => {
        setLoadingDetails(false);
        setError(true);
        setLoadingSummary(false);
        console.error(error);
      });
  };

  const handleAddEntry = () => {
    setLoadingEntries(true);
    fetch(`/api/entries`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ project: project, minutes: minutes, date: date }),
    })
      .then((response) => response.json())
      .then((data) => {
        setLoadingEntries(false);
        setData((prevData) => [...prevData, data]);
        setMinutes(0);
        setDate(new Date());
        setProject('api-server');
      })
      .catch((error) => {
        setLoadingEntries(false);
        setError(true);
        console.error(error);
      });
  };

  const handleDeleteEntry = (id) => {
    fetch(`/api/entries/${id}`, {
      method: 'DELETE',
    })
      .then((response) => response.json())
      .then((data) => {
        const updatedData = data.map((entry) => {
          if (entry.id !== id) {
            return entry;
          }
          return {
            ...entry,
            active: false,
          };
        });
        setData(updatedData);
      })
      .catch((error) => {
        console.error(error);
      });
  };

  const handleDeleteProject = (project) => {
    fetch(`/api/projects/${project}`, {
      method: 'DELETE',
    })
      .then((response) => response.json())
      .then((data) => {
        setLoadingDetails(false);
        setData((prevData) => prevData.filter((entry) => entry.project !== project));
      })
      .catch((error) => {
        setLoadingDetails(false);
        setError(true);
        console.error(error);
      });
  };

  return (
    <div>
      <hr></hr>
      <div>
        <p>Projects</p>
      </div>
      <hr></hr>
      <div>
        <p>Summary</p>
      </div>
      <hr></hr>
      <div>
        <form onSubmit={handleFormSubmit}>
          <div>
            <input
              type="text"
              placeholder="Project"
              value={project}
              onChange={(e) => handleProjectChange(e.target.value)}
            />
          </div>
          <div>
            <input
              type="number"
              placeholder="Minutes"
              value={minutes}
              onChange={(e) => handleMinutesChange(e.target.value)}
            />
          </div>
          <div>
            <input
              type="date"
              value={date}
              onChange={(e) => handleDateChange(e.target.value)}
            />
          </div>
          <div>
            <input
              type="text"
              placeholder="Note"
              value={note}
              onChange={(e) => handleNoteChange(e.target.value)}
            />
          </div>
          <div>
            <button type="submit">Add</button>
          </div>
        </form>
      </div>
      <hr></hr>
      <div>
        <div>
          {loadingDetails && (
            <p>Loading details...</p>
          )}
          {loadingEntries && (
            <p>Loading entries...</p>
          )}
          {loadingSummary && (
            <p>Loading summary...</p>
          )}
        </div>
        <div>
          <div>
            {summary.by_project && Object.keys(summary.by_project).length > 0 ? (
              <p>By Project:</p>
            ) : (
              <p>No projects yet</p>
            )}
            {Object.keys(summary.by_project).length > 0 && (
              <ul>
                {Object.keys(summary.by_project).map((project) => (
                  <li key={project}>{project}</li>
                ))}
              </ul>
            )}
          </div>
          <div>
            {summary.by_day && Object.keys(summary.by_day).length > 0 ? (
              <p>By Day:</p>
            ) : (
              <p>No days yet</p>
            )}
            {Object.keys(summary.by_day).length > 0 && (
              <ul>
                {Object.keys(summary.by_day).map((day) => (
                  <li key={day}>{day}</li>
                ))}
              </ul>
            )}
          </div>
          <div>
            {summary.active_projects && Object.keys(summary.active_projects).length > 0 ? (
              <p>Active Projects:</p>
            ) : (
              <p>No active projects yet</p>
            )}
            {Object.keys(summary.active_projects).length > 0 && (
              <ul>
                {Object.keys(summary.active_projects).map((project) => (
                  <li key={project}>{project}</li>
                ))}
              </ul>
            )}
          </div>
          <div>
            {summary.busiest_day && Object.keys(summary.busiest_day).length > 0 ? (
              <p>Busiest Day:</p>
            ) : (
              <p>No busiest day yet</p>
            )}
            {Object.keys(summary.busiest_day).length > 0 && (
              <ul>
                {Object.keys(summary.busiest_day).map((day) => (
                  <li key={day}>{day}</li>
                ))}
              </ul>
            )}
          </div>
          {summary.total_minutes > 0 && (
            <p>Summary:</p>
          )}
          {summary.total_minutes > 0 ? (
            <p>
              Total Minutes: <strong>{summary.total_minutes}</strong>
            </p>
          ) : (
            <p>Summary is empty</p>
          )}
        </div>
      </div>
      <hr></hr>
      <div>
        {data.map((entry) => (
          <div key={entry.id}>
            <div>
              <p>
                {entry.project} - {entry.minutes} min - {entry.date.toDateString()} - {entry.note}
              </p>
              <div>
                <button onClick={() => handleDeleteEntry(entry.id)}>Delete</button>
                <button onClick={() => handleDeleteProject(entry.project)}>Delete Project</button>
              </div>
            </div>
          </div>
        ))}
      </div>
      <hr></hr>
      <div>
        <button onClick={handleAddEntry}>Add Entry</button>
      </div>
    </div>
  );
}

module.exports = App;

