    busiest_day = None
    if active_projects > 0:
        busiest_day = max(by_day, key=lambda date: by_day[date])
    return {
        'total_minutes': sum(by_project.values()),
        'by_project': by_project,
        'by_day': by_day,
        'active_projects': active_projects,
        'busiest_day': busiest_day
